import hashlib
import hmac
import os
import time
import json
import re
from typing import Optional, Dict, Tuple
import secrets
from urllib.parse import unquote


class SecureTokenBucket:
    """Rate limiter with cryptographic client fingerprinting."""

    def __init__(self, capacity: int = 100, refill_rate: float = 10.0):
        self.capacity = capacity
        self.refill_rate = refill_rate
        self._buckets: Dict[str, Tuple[float, float]] = {}

    def _fingerprint(self, client_id: str) -> str:
        """Create a fixed-length fingerprint to prevent memory exhaustion."""
        return hashlib.sha256(client_id.encode('utf-8')).hexdigest()[:16]

    def allow_request(self, client_id: str) -> bool:
        fp = self._fingerprint(client_id)
        now = time.time()
        if fp in self._buckets:
            tokens, last_time = self._buckets[fp]
            elapsed = now - last_time
            tokens = min(self.capacity, tokens + elapsed * self.refill_rate)
            if tokens >= 1.0:
                self._buckets[fp] = (tokens - 1.0, now)
                return True
            else:
                self._buckets[fp] = (tokens, last_time)
                return False
        else:
            self._buckets[fp] = (self.capacity - 1.0, now)
            return True


class SessionStore:
    """Manages authenticated sessions with HMAC-signed session cookies."""

    def __init__(self):
        self._signing_key = secrets.token_bytes(32)
        self._sessions: Dict[str, dict] = {}

    def create_session(self, user_id: str, role: str) -> str:
        session_id = secrets.token_hex(16)
        self._sessions[session_id] = {
            'user_id': user_id,
            'role': role,
            'created_at': time.time(),
            'last_access': time.time()
        }
        signature = self._sign_session_id(session_id)
        return f"{session_id}.{signature}"

    def _sign_session_id(self, session_id: str) -> str:
        return hmac.new(
            self._signing_key,
            session_id.encode('utf-8'),
            hashlib.sha256
        ).hexdigest()

    def validate_session(self, cookie: str) -> Optional[dict]:
        if not cookie or '.' not in cookie:
            return None
        parts = cookie.split('.', 1)
        if len(parts) != 2:
            return None
        session_id, provided_sig = parts
        expected_sig = self._sign_session_id(session_id)
        # Constant-time comparison to prevent timing attacks
        if not hmac.compare_digest(provided_sig, expected_sig):
            return None
        session = self._sessions.get(session_id)
        if session is None:
            return None
        # Check session expiry (30 minutes)
        if time.time() - session['last_access'] > 1800:
            del self._sessions[session_id]
            return None
        session['last_access'] = time.time()
        return session

    def revoke_session(self, cookie: str) -> bool:
        if not cookie or '.' not in cookie:
            return False
        session_id = cookie.split('.', 1)[0]
        if session_id in self._sessions:
            del self._sessions[session_id]
            return True
        return False


class AccessControl:
    """Role-based access control with path-based permissions."""

    ROLE_HIERARCHY = {
        'admin': 3,
        'editor': 2,
        'viewer': 1,
        'anonymous': 0
    }

    # Permission matrix: (path_pattern, minimum_role_level)
    PERMISSIONS = [
        (re.compile(r'^/api/admin(/.*)?$'), 'admin'),
        (re.compile(r'^/api/content(/.*)?$'), 'editor'),
        (re.compile(r'^/api/view(/.*)?$'), 'viewer'),
        (re.compile(r'^/public(/.*)?$'), 'anonymous'),
    ]

    def check_access(self, path: str, role: str) -> bool:
        """Check if a role has access to the given path.

        Uses a first-match strategy: the first matching permission
        rule determines the required role level.
        """
        user_level = self.ROLE_HIERARCHY.get(role, 0)

        for pattern, required_role in self.PERMISSIONS:
            if pattern.match(path):
                required_level = self.ROLE_HIERARCHY.get(required_role, 0)
                return user_level >= required_level

        # Default deny for unmatched paths
        return False


class RequestHandler:
    """HTTP request handler with security middleware."""

    def __init__(self):
        self.rate_limiter = SecureTokenBucket()
        self.session_store = SessionStore()
        self.access_control = AccessControl()
        self._users_db = {
            'admin': {'password_hash': self._hash_password('admin123'), 'role': 'admin'},
            'editor': {'password_hash': self._hash_password('edit456'), 'role': 'editor'},
            'viewer': {'password_hash': self._hash_password('view789'), 'role': 'viewer'},
        }
        # Dummy hash used to keep login timing constant when a user is
        # not found, preventing username enumeration via timing analysis.
        self._dummy_password_hash = self._hash_password(secrets.token_hex(16))

    def _hash_password(self, password: str) -> str:
        salt = secrets.token_hex(16)
        hash_val = hashlib.pbkdf2_hmac(
            'sha256',
            password.encode('utf-8'),
            salt.encode('utf-8'),
            iterations=100000
        ).hex()
        return f"{salt}:{hash_val}"

    def _verify_password(self, password: str, stored: str) -> bool:
        try:
            salt, expected_hash = stored.split(':', 1)
            actual_hash = hashlib.pbkdf2_hmac(
                'sha256',
                password.encode('utf-8'),
                salt.encode('utf-8'),
                iterations=100000
            ).hex()
            return hmac.compare_digest(actual_hash, expected_hash)
        except (ValueError, AttributeError):
            return False

    def _normalize_path(self, raw_path: str) -> str:
        """Normalize request path to prevent traversal attacks."""
        # Single-pass decode using stdlib
        path = unquote(raw_path)

        # Remove path traversal sequences
        # Resolve by splitting on / and removing .. components
        parts = path.split('/')
        resolved = []
        for part in parts:
            if part == '..':
                if resolved:
                    resolved.pop()
            elif part == '.':
                continue
            else:
                resolved.append(part)
        path = '/'.join(resolved)

        # Collapse multiple slashes
        path = re.sub(r'/+', '/', path)

        # Ensure leading slash
        if not path.startswith('/'):
            path = '/' + path

        # Reject any remaining percent-encoded characters after decode
        # This prevents double-encoding attacks
        if '%' in path:
            path = '/invalid'

        return path

    def handle_request(self, method: str, raw_path: str, headers: dict, body: Optional[str] = None) -> dict:
        """Main request handler with full security pipeline."""
        # Step 1: Rate limiting
        client_ip = headers.get('X-Real-IP', headers.get('Remote-Addr', '127.0.0.1'))
        if not self.rate_limiter.allow_request(client_ip):
            return {'status': 429, 'body': 'Rate limit exceeded'}

        # Step 2: Path normalization
        normalized_path = self._normalize_path(raw_path)

        # Step 3: Authentication
        session = None
        session_cookie = headers.get('Cookie', '')
        if 'session=' in session_cookie:
            token = session_cookie.split('session=')[1].split(';')[0]
            session = self.session_store.validate_session(token)

        # Step 4: Handle login separately
        if normalized_path == '/api/login' and method == 'POST':
            return self._handle_login(body)

        # Step 5: Determine role
        role = session['role'] if session else 'anonymous'

        # Step 6: Authorization check
        if not self.access_control.check_access(normalized_path, role):
            return {'status': 403, 'body': 'Access denied'}

        # Step 7: Route to handler
        return self._route_request(method, normalized_path, session)

    def _handle_login(self, body: Optional[str]) -> dict:
        if not body:
            return {'status': 400, 'body': 'Missing credentials'}
        try:
            creds = json.loads(body)
        except json.JSONDecodeError:
            return {'status': 400, 'body': 'Invalid JSON'}

        username = creds.get('username', '')
        password = creds.get('password', '')

        if not username or not password:
            return {'status': 400, 'body': 'Missing username or password'}

        user = self._users_db.get(username)
        if not user:
            # Perform a dummy verification to keep timing constant and
            # prevent username enumeration via timing side-channels.
            self._verify_password(password, self._dummy_password_hash)
            return {'status': 401, 'body': 'Invalid credentials'}
        if not self._verify_password(password, user['password_hash']):
            return {'status': 401, 'body': 'Invalid credentials'}

        cookie = self.session_store.create_session(username, user['role'])
        return {
            'status': 200,
            'body': json.dumps({'message': 'Login successful'}),
            'headers': {'Set-Cookie': f'session={cookie}; HttpOnly; SameSite=Strict'}
        }

    def _route_request(self, method: str, path: str, session: Optional[dict]) -> dict:
        if path.startswith('/api/admin'):
            return {'status': 200, 'body': json.dumps({'admin_panel': True, 'users': list(self._users_db.keys())})}
        elif path.startswith('/api/content'):
            return {'status': 200, 'body': json.dumps({'content': 'editable content'})}
        elif path.startswith('/api/view'):
            return {'status': 200, 'body': json.dumps({'data': 'viewable data'})}
        elif path.startswith('/public'):
            return {'status': 200, 'body': json.dumps({'public': True})}
        else:
            return {'status': 404, 'body': 'Not found'}
